package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct { // 01 LOAN-REC, 21 bytes
	LrAcct      string          // PIC X(6) @0 len=6
	LrPrincipal decimal.Decimal // PIC 9(7)V99 @6 len=9
	LrRate      decimal.Decimal // PIC 9(2)V99 @15 len=4
	LrYears     int64           // PIC 9(2) @19 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                     // PIC X len=1 = "N"
var WsInterest decimal.Decimal = decimal.Zero // PIC 9(9)V99 len=11 = 0
var WsTotal decimal.Decimal = decimal.Zero    // PIC 9(11)V99 len=13 = 0
var WsCount int64 = 0                         // PIC 9(5) len=5 = 0
var WsPrinEd string                           // PIC Z,ZZZ,ZZ9.99 len=12
var WsIntEd string                            // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsTotalEd string                          // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var loanRec LoanRec

// file handling for LOAN-FILE
var loanLines []string
var loanIdx int

func isInputDone() bool {
	return WsEofFlag == "Y"
}
func setInputDone(v bool) {
	if v {
		WsEofFlag = "Y"
	} else {
		WsEofFlag = "N"
	}
}

// Helpers for numeric storage (low-order truncation)
func storeDecimal(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// Truncate to scale already done by caller; just apply overflow
	totalDigits := intDigits + int(scale)
	// Scale value to integer: val * 10^scale
	scalePow := decimal.New(1, scale) // 10^scale
	scaled := val.Mul(scalePow)
	// Truncate toward zero to remove any extra fractional beyond scale (should be none)
	scaled = scaled.Truncate(0)
	// Keep low-order totalDigits digits
	powTotal := decimal.New(1, int32(totalDigits))
	// For positive numbers mod; for negative preserve sign
	neg := scaled.IsNegative()
	if neg {
		scaled = scaled.Abs()
	}
	if totalDigits > 0 {
		// if scaled >= powTotal, keep low order
		if scaled.GreaterOrEqual(powTotal) {
			scaled = scaled.Mod(powTotal)
		}
	}
	if neg {
		scaled = scaled.Neg()
	}
	// back to decimal with scale
	return scaled.Div(scalePow)
}

// Parsing helpers
func parseDecimalField(s string, scale int32) decimal.Decimal {
	// s may contain spaces; digits only expected
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return decimal.Zero
	}
	// Remove any internal spaces? COBOL would have digits only
	// Keep only digits (and sign)
	// If contains non-digit, try to handle
	filtered := ""
	for _, r := range trimmed {
		if r >= '0' && r <= '9' {
			filtered += string(r)
		} else if r == '-' || r == '+' {
			filtered += string(r)
		}
	}
	if filtered == "" || filtered == "+" || filtered == "-" {
		return decimal.Zero
	}
	d, err := decimal.NewFromString(filtered)
	if err != nil {
		return decimal.Zero
	}
	if scale != 0 {
		d = d.Shift(-scale)
	}
	return d
}

func parseIntField(s string) int64 {
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return 0
	}
	filtered := ""
	for _, r := range trimmed {
		if r >= '0' && r <= '9' || r == '-' || r == '+' {
			filtered += string(r)
		}
	}
	if filtered == "" {
		return 0
	}
	var v int64
	fmt.Sscanf(filtered, "%d", &v)
	return v
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func formatEdited(val decimal.Decimal, picture string) string {
	// picture like Z,ZZZ,ZZ9.99
	dotIdx := strings.Index(picture, ".")
	var intPic string
	var fracPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	intDigitsPic := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigitsPic++
		}
	}
	fracDigitsPic := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracDigitsPic++
		}
	}

	absVal := val.Abs()

	// integer part low-order truncation
	intPart := absVal.Truncate(0)
	powInt := decimal.New(1, int32(intDigitsPic))
	if intDigitsPic > 0 && intPart.GreaterOrEqual(powInt) {
		intPart = intPart.Mod(powInt)
	}
	// build intStr zero padded to intDigitsPic
	intStr := intPart.StringFixed(0) // no decimal places
	// Remove sign if any (abs)
	if strings.HasPrefix(intStr, "-") {
		intStr = intStr[1:]
	}
	// intStr may be like "0" for zero
	if len(intStr) < intDigitsPic {
		intStr = strings.Repeat("0", intDigitsPic-len(intStr)) + intStr
	} else if len(intStr) > intDigitsPic {
		// should have been modded, but handle last digits
		intStr = intStr[len(intStr)-intDigitsPic:]
	}

	// fractional part
	fracStr := ""
	if fracDigitsPic > 0 {
		powFrac := decimal.New(1, int32(fracDigitsPic))
		scaled := absVal.Mul(powFrac)
		// fractional digits are scaled mod powFrac
		scaledTrunc := scaled.Truncate(0)
		fracPart := scaledTrunc.Mod(powFrac)
		// need absolute
		if fracPart.IsNegative() {
			fracPart = fracPart.Abs()
		}
		fs := fracPart.StringFixed(0)
		if strings.HasPrefix(fs, "-") {
			fs = fs[1:]
		}
		if len(fs) < fracDigitsPic {
			fs = strings.Repeat("0", fracDigitsPic-len(fs)) + fs
		} else if len(fs) > fracDigitsPic {
			fs = fs[len(fs)-fracDigitsPic:]
		}
		fracStr = fs
	}

	// Build integer section with Z suppression
	intRunes := []rune(intPic)
	outInt := make([]rune, len(intRunes))
	// placeholder index
	phIdx := 0
	suppressing := true
	for i, ch := range intRunes {
		if ch == ',' {
			if suppressing {
				outInt[i] = ' '
			} else {
				outInt[i] = ','
			}
		} else if ch == 'Z' || ch == '9' {
			digit := rune(intStr[phIdx])
			phIdx++
			if suppressing {
				if ch == 'Z' && digit == '0' {
					outInt[i] = ' '
					// remain suppressing
				} else {
					outInt[i] = digit
					suppressing = false
				}
			} else {
				outInt[i] = digit
			}
		} else {
			outInt[i] = ch
		}
	}

	// Assemble final
	var result string
	result = string(outInt)
	if dotIdx >= 0 {
		result += "."
		// fracPic characters are all 9/Z, just emit fracStr digits in order
		// The picture fractional length equals fracDigitsPic, so just append fracStr
		// But if picture contains other chars (unlikely), handle similarly
		fracRunes := []rune(fracPic)
		fracIdx := 0
		for _, ch := range fracRunes {
			if ch == 'Z' || ch == '9' {
				if fracIdx < len(fracStr) {
					result += string(fracStr[fracIdx])
				} else {
					result += "0"
				}
				fracIdx++
			} else {
				result += string(ch)
			}
		}
	}
	// Ensure length equals picture length (should already)
	if len(result) < len(picture) {
		result = strings.Repeat(" ", len(picture)-len(result)) + result
	} else if len(result) > len(picture) {
		result = result[len(result)-len(picture):]
	}
	return result
}

func formatWsCount() string {
	// PIC 9(5) zero padded to 5, low-order truncation
	v := WsCount % 100000
	if v < 0 {
		v = -v
	}
	return fmt.Sprintf("%05d", v)
}

// Paragraphs
func READPARA() {
	if loanIdx >= len(loanLines) {
		setInputDone(true)
		return
	}
	line := loanLines[loanIdx]
	loanIdx++
	// pad to 21 as per spec (already padded when loaded, but ensure)
	if len(line) < 21 {
		line = line + strings.Repeat(" ", 21-len(line))
	} else if len(line) > 21 {
		line = line[:21]
	}
	loanRec.LrAcct = line[0:6]
	loanRec.LrPrincipal = parseDecimalField(line[6:15], 2)
	loanRec.LrRate = parseDecimalField(line[15:19], 2)
	loanRec.LrYears = parseIntField(line[19:21])
}

func PROCESSPARA() {
	// COMPUTE WS-INTEREST ROUNDED = LR-PRINCIPAL * LR-RATE * LR-YEARS / 100
	// multiply before dividing, shift -2 for /100
	y := decimal.NewFromInt(loanRec.LrYears)
	comp := loanRec.LrPrincipal.Mul(loanRec.LrRate).Mul(y).Shift(-2)
	comp = comp.Round(2)
	WsInterest = storeDecimal(comp, 9, 2)

	// ADD WS-INTEREST TO WS-TOTAL
	sum := WsTotal.Add(WsInterest)
	WsTotal = storeDecimal(sum, 11, 2)

	// ADD 1 TO WS-COUNT (with truncation to 5 digits)
	WsCount = WsCount + 1
	// apply low-order truncation for display/storage
	if WsCount >= 100000 || WsCount < 0 {
		// keep low 5 digits
		WsCount = WsCount % 100000
		if WsCount < 0 {
			WsCount = -WsCount
		}
	}

	// MOVE to edited
	WsPrinEd = formatEdited(loanRec.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")

	fmt.Printf("%s %s %s\n", loanRec.LrAcct, WsPrinEd, WsIntEd)

	READPARA()
}

func SUMMARYPARA() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("RECORDS: %s\n", formatWsCount())
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

func MAINPARA() {
	// OPEN INPUT LOAN-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not exists, treat as empty
		loanLines = []string{}
	} else {
		scanner := bufio.NewScanner(f)
		// increase buffer for long lines? record is short
		var lines []string
		for scanner.Scan() {
			txt := scanner.Text()
			// scanner already strips \n and \r, handle as is
			// Pad handled in READPARA, but also handle line shorter than record length concept: pad later
			lines = append(lines, txt)
		}
		f.Close()
		loanLines = lines
	}
	loanIdx = 0
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	// CLOSE LOAN-FILE handled
	SUMMARYPARA()
}

func main() {
	MAINPARA()
}

